const conf = $('Configuración').item.json;
const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const marker = conf.topic_id.replace('_', '·');
const lines = String($('Extraer texto del temario').item.json.data).split(NL);
const section = [];
let on = false;
for (const raw of lines) {
  const t = raw.replace(CR, '');
  if (t.indexOf(marker) >= 0) { on = true; section.push(t); continue; }
  if (on && (t.indexOf('·S0') >= 0 || t.indexOf('·BLOQUE') >= 0)) break;
  if (on) section.push(t);
}
const podcast = $('Extraer JSON del podcast').item.json.data.podcast;
const podcastText = 'Título: ' + podcast.titulo + NL + podcast.turnos.map((x) => x.hablante + ': ' + x.texto).join(NL);
return {
  json: {
    run_id: conf.run_id,
    topic_id: conf.topic_id,
    class_url: conf.class_url,
    class_video_path: conf.class_video_path,
    cfg: conf.cfg,
    ctx: { temario: section.join(NL), podcast: podcastText, official: $json.text }
  }
};

const s = $json;
const NL = String.fromCharCode(10);
const system = 'Eres editor pedagógico de AccesoPro (preparación de pruebas de acceso para adultos). Divides un tema de Matemáticas de Grado Superior (Comunidad Valenciana) en ideas independientes y accionables para vídeos cortos de 30 a 60 segundos. Cada idea es UN concepto, regla o error típico concreto que se pueda explicar con UN ejemplo numérico sencillo. Las ideas no pueden repetirse ni compartir ejemplo numérico entre sí. Usa solo contenido presente en el temario y en el guion de podcast.';
const user = 'TEMARIO ACCESOPRO DEL TEMA:' + NL + s.ctx.temario + NL + NL + 'GUION DE PODCAST DEL TEMA (contenido ya elaborado):' + NL + s.ctx.podcast + NL + NL + 'Divide el tema en exactamente ' + s.cfg.n_scripts + ' ideas DISTINTAS que, juntas, cubran TODOS los apartados del temario: operaciones (puedes dedicar una idea a las fracciones y otra al orden de las operaciones y las potencias), ordenación y representación en la recta, y propiedades de los números reales (conmutativa, distributiva, factor común). Cada idea debe tener un ejemplo propio distinto del de las demás. Prioriza errores típicos de examen. Entrega las ideas con la herramienta.';
const tool = {
  name: 'entregar_ideas',
  description: 'Entrega la lista de ideas para vídeos cortos',
  input_schema: {
    type: 'object',
    properties: {
      ideas: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            titulo: { type: 'string', description: 'Título interno corto de la idea' },
            apartado_temario: { type: 'string', description: 'Apartado del temario que cubre' },
            puntos_clave: { type: 'array', items: { type: 'string' }, description: 'Puntos clave que deben aparecer' },
            error_tipico: { type: 'string', description: 'Error típico de examen relacionado' }
          },
          required: ['titulo', 'apartado_temario', 'puntos_clave', 'error_tipico']
        }
      }
    },
    required: ['ideas']
  }
};
const req = { model: s.cfg.writer_model, max_tokens: 2000, temperature: 0.3, system: system, messages: [{ role: 'user', content: user }], tools: [tool], tool_choice: { type: 'tool', name: 'entregar_ideas' } };
return { json: Object.assign({}, s, { req: req }) };

const s = $('Prompt dividir en ideas').first().json;
const r = $input.first().json;
const block = (r.content || []).find((b) => b.type === 'tool_use');
if (!block) throw new Error('Claude no devolvió las ideas');
const ideas = block.input.ideas.slice(0, s.cfg.n_scripts);
const u = r.usage || {};
const cost = ((u.input_tokens || 0) * s.cfg.price_writer_in + (u.output_tokens || 0) * s.cfg.price_writer_out) / 1000000;
const tag = s.topic_id.replace('_', '');
return ideas.map((idea, i) => ({
  json: {
    piece_id: tag + '-idea-' + (i + 1),
    run_id: s.run_id,
    kind: 'script',
    title: idea.titulo,
    source_ref: s.topic_id + ' · ' + idea.apartado_temario,
    attempts: 0,
    idea: idea,
    ctx: s.ctx,
    cfg: s.cfg,
    costs: { llm: cost / ideas.length, voice: 0, stt: 0 }
  }
}));

const ctx = $('Construir contexto').first().json;
const chunks = $('Listar trozos de audio').all();
const results = $input.all();
const segments = [];
const words = [];
let minutes = 0;
results.forEach((it, i) => {
  const off = chunks[i].json.offset;
  const r = it.json;
  (r.segments || []).forEach((sg) => segments.push({ start: sg.start + off, end: sg.end + off, text: String(sg.text).trim() }));
  (r.words || []).forEach((w) => words.push({ w: String(w.word).trim(), s: w.start + off, e: w.end + off }));
  minutes += (r.duration || 0) / 60;
});
return [{ json: { run_id: ctx.run_id, topic_id: ctx.topic_id, class_video_path: ctx.class_video_path, cfg: ctx.cfg, ctx: ctx.ctx, segments: segments, words: words, duration_min: minutes, stt_cost: minutes * ctx.cfg.price_whisper_per_min } }];

const s = $('Unir transcripción con marcas de tiempo').first().json;
const rows = $('Tabla · leer rangos ya usados').all().map((i) => i.json).filter((r) => r && r.piece_id && r.kind === 'clip' && (r.status === 'publicada' || r.status === 'rechazada'));
const NL = String.fromCharCode(10);
const toSec = (x) => { const q = x.split(':'); return Number(q[0]) * 60 + Number(q[1]); };
const avoid = rows.map((r) => { const m = String(r.source_ref || '').split(' ')[1]; if (!m || m.indexOf('-') < 0) return null; const p = m.split('-'); return toSec(p[0]) + '-' + toSec(p[1]) + ' s'; }).filter((x) => x);
const transcript = s.segments.map((sg) => '[' + Math.round(sg.start) + 's] ' + sg.text).join(NL);
const system = 'Eres editor pedagógico de AccesoPro. Recibes la transcripción con marcas de tiempo (segundos) de una clase en directo de Matemáticas (acceso a Grado Superior, Comunidad Valenciana) y debes elegir los momentos que funcionen como clips independientes para YouTube. Criterio PEDAGÓGICO, no cortes por tiempo: elige (a) explicaciones completas de un concepto o procedimiento, (b) trucos de examen, (c) errores típicos que la profesora señala. REQUISITOS DE CADA CLIP: 1) Debe entenderse SIN el resto de la clase: empieza en una frase completa que presente la idea (nunca en mitad de frase, ni con conectores como y, pero, entonces, ni con referencias a lo de antes, al ejercicio anterior o a la pantalla sin explicar) y termina cuando la idea queda cerrada. 2) Debe ser matemáticamente correcto: descarta fragmentos con errores sin corregir, dudas, autocorrecciones del profesor o afirmaciones absolutas incorrectas; antes de elegir un clip, comprueba tú mismo los cálculos y las reglas que se dicen en él. 3) Descarta saludos, cuestiones técnicas, organización de la clase y charla sin contenido. 4) Duración de cada clip: entre ' + s.cfg.clip_min_seconds + ' y ' + s.cfg.clip_max_seconds + ' segundos. 5) Sin solapes entre clips y REPARTIDOS por toda la clase (busca candidatos en todas las partes, no solo al principio). Usa los tiempos exactos de la transcripción y escoge el inicio en el segundo donde empieza la frase.';
const evitar = avoid.length ? NL + NL + 'RANGOS YA USADOS O RECHAZADOS (no los repitas ni te solapes con ellos): ' + avoid.join(', ') : '';
const user = 'TEMARIO ACCESOPRO DEL TEMA:' + NL + s.ctx.temario + NL + NL + 'TRANSCRIPCIÓN DE LA CLASE:' + NL + transcript + evitar + NL + NL + 'Elige entre ' + s.cfg.clips_min + ' y ' + s.cfg.clips_max + ' momentos NUEVOS y entrégalos con la herramienta.';
const tool = {
  name: 'entregar_momentos',
  description: 'Entrega los momentos seleccionados',
  input_schema: {
    type: 'object',
    properties: {
      momentos: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            inicio_seg: { type: 'number', description: 'Segundo de inicio del clip' },
            fin_seg: { type: 'number', description: 'Segundo de fin del clip' },
            tipo: { type: 'string', enum: ['explicacion_completa', 'truco_de_examen', 'error_tipico'] },
            titulo: { type: 'string', description: 'Título interno corto' },
            justificacion: { type: 'string', description: 'Por qué tiene valor propio y se entiende sin el resto de la clase' }
          },
          required: ['inicio_seg', 'fin_seg', 'tipo', 'titulo', 'justificacion']
        }
      }
    },
    required: ['momentos']
  }
};
const req = { model: s.cfg.writer_model, max_tokens: 3500, temperature: 0.2, system: system, messages: [{ role: 'user', content: user }], tools: [tool], tool_choice: { type: 'tool', name: 'entregar_momentos' } };
return { json: Object.assign({}, s, { req: req }) };

const s = $('Prompt detectar momentos con valor propio').first().json;
const r = $input.first().json;
const block = (r.content || []).find((b) => b.type === 'tool_use');
if (!block) throw new Error('Claude no devolvió los momentos');
const u = r.usage || {};
const cost = ((u.input_tokens || 0) * s.cfg.price_writer_in + (u.output_tokens || 0) * s.cfg.price_writer_out) / 1000000;
const segs = s.segments;
const words = s.words;
const endsSentence = (t) => /[.?!]$/.test(String(t).trim());
const idxAt = (t) => {
  let best = 0;
  let bestD = Infinity;
  segs.forEach((sg, i) => {
    const d = t >= sg.start && t <= sg.end ? 0 : Math.min(Math.abs(t - sg.start), Math.abs(t - sg.end));
    if (d < bestD) { bestD = d; best = i; }
  });
  return best;
};
const moments = block.input.momentos.slice().sort((a, b) => a.inicio_seg - b.inicio_seg);
const valid = [];
let lastEnd = -1;
for (const m of moments) {
  let start = Number(m.inicio_seg);
  let end = Number(m.fin_seg);
  if (!(end > start)) continue;
  const i0 = idxAt(start);
  let j = i0;
  let bestJ = -1;
  let bestDist = Infinity;
  for (let k = Math.max(0, i0 - 3); k <= Math.min(segs.length - 1, i0 + 3); k++) {
    const startsSentence = k === 0 || endsSentence(segs[k - 1].text);
    if (startsSentence && Math.abs(segs[k].start - start) <= 15 && Math.abs(k - i0) < bestDist) { bestDist = Math.abs(k - i0); bestJ = k; }
  }
  if (bestJ >= 0) j = bestJ;
  start = segs[j].start;
  let e0 = idxAt(end);
  let guard = 0;
  while (e0 < segs.length - 1 && !endsSentence(segs[e0].text) && guard < 4) { e0++; guard++; }
  while (e0 > j && segs[e0].end - start > s.cfg.clip_max_seconds - 1) { e0--; while (e0 > j && !endsSentence(segs[e0].text)) e0--; }
  end = segs[e0].end;
  start = Math.max(0, start - 0.15);
  end = end + 0.3;
  const dur = end - start;
  if (dur < s.cfg.clip_min_seconds || dur > s.cfg.clip_max_seconds) continue;
  if (start < lastEnd) continue;
  lastEnd = end;
  valid.push({ m: m, start: start, end: end });
}
const chosen = valid.slice(0, s.cfg.clips_max);
const two = (n) => String(Math.floor(n)).padStart(2, '0');
const mmss = (t) => Math.floor(t / 60) + ':' + two(t % 60);
return chosen.map((v) => {
  const cw = words.filter((w) => w.s >= v.start - 0.05 && w.e <= v.end + 0.05).map((w) => ({ w: w.w, s: Math.max(0, w.s - v.start), e: Math.max(0, w.e - v.start) }));
  const text = segs.filter((sg) => sg.end > v.start && sg.start < v.end).map((sg) => sg.text).join(' ');
  return {
    json: {
      piece_id: 'CLASE-' + two(v.start / 60) + two(v.start % 60),
      run_id: s.run_id,
      kind: 'clip',
      title: v.m.titulo,
      source_ref: 'clase ' + mmss(v.start) + '-' + mmss(v.end) + ' · ' + v.m.tipo,
      attempts: 0,
      text: text,
      clip: { start: v.start, end: v.end, type: v.m.tipo, title: v.m.titulo, justificacion: v.m.justificacion, words: cw, source_video: s.class_video_path },
      ctx: { temario: s.ctx.temario, podcast: '', official: s.ctx.official },
      cfg: s.cfg,
      costs: { llm: cost / chosen.length, voice: 0, stt: s.stt_cost / chosen.length }
    }
  };
});

const pieces = $('Unir piezas de texto y de clase').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.piece_id);
if (!pieces.length) return [];
const cfg = pieces[0].cfg;
const force = cfg.force_ids || [];
const today = new Date().toISOString().slice(0, 10);
const todayRows = rows.filter((r) => String(r.updatedAt || '').slice(0, 10) === today);
const spent = todayRows.reduce((a, r) => a + (Number(r.cost_total_usd) || 0), 0);
if (spent >= cfg.daily_budget_usd) return [];
const toSec = (x) => { const q = x.split(':'); return Number(q[0]) * 60 + Number(q[1]); };
const rng = (ref) => { const m = String(ref || '').split(' ')[1]; if (!m || m.indexOf('-') < 0) return null; const p = m.split('-'); const a = toSec(p[0]); const b = toSec(p[1]); return isNaN(a) || isNaN(b) ? null : [a, b]; };
const overlap = (a, b) => Math.max(0, Math.min(a[1], b[1]) - Math.max(a[0], b[0])) / Math.min(a[1] - a[0], b[1] - b[0]);
const usedRanges = rows.filter((r) => r.kind === 'clip' && (r.status === 'publicada' || r.status === 'rechazada')).map((r) => rng(r.source_ref)).filter((x) => x);
const repeatedClip = (p) => { if (p.kind !== 'clip') return false; const a = rng(p.source_ref); return !!a && usedRanges.some((b) => overlap(a, b) > 0.5); };
const prev = {};
rows.forEach((r) => { prev[r.piece_id] = r; });
const published = {};
rows.forEach((r) => { if (r.status === 'publicada' && force.indexOf(r.piece_id) < 0) published[r.piece_id] = true; });
const pending = pieces.filter((p) => !published[p.piece_id] && !repeatedClip(p)).map((p) => {
  const r = prev[p.piece_id];
  if (!r) return p;
  const c = p.costs;
  return Object.assign({}, p, { costs: { llm: c.llm + (Number(r.cost_llm_usd) || 0), voice: c.voice + (Number(r.cost_voice_usd) || 0), stt: c.stt + (Number(r.cost_stt_usd) || 0) } });
});
const scripts = pending.filter((p) => p.kind === 'script');
const clips = pending.filter((p) => p.kind === 'clip');
const pubClips = rows.filter((r) => r.status === 'publicada' && r.kind === 'clip').length;
const pubScripts = rows.filter((r) => r.status === 'publicada' && r.kind === 'script').length;
const clipsFirst = pubClips < pubScripts;
let mixed = [];
for (let i = 0; i < Math.max(scripts.length, clips.length); i++) {
  if (clipsFirst) {
    if (clips[i]) mixed.push(clips[i]);
    if (scripts[i]) mixed.push(scripts[i]);
  } else {
    if (scripts[i]) mixed.push(scripts[i]);
    if (clips[i]) mixed.push(clips[i]);
  }
}
if (cfg.publish_enabled) {
  const uploadedToday = todayRows.filter((r) => r.status === 'publicada' && force.indexOf(r.piece_id) < 0).length;
  mixed = mixed.slice(0, Math.max(0, cfg.max_uploads_per_day - uploadedToday + 1));
}
return mixed.slice(0, cfg.max_pieces_per_run).map((p) => ({ json: p }));

const rows = $input.all().map((i) => i.json).filter((r) => r && r.piece_id);
const count = {};
let cost = 0;
rows.forEach((r) => { count[r.status] = (count[r.status] || 0) + 1; cost += Number(r.cost_total_usd) || 0; });
return [{ json: { piezas: rows.length, por_estado: count, coste_total_usd: Math.round(cost * 10000) / 10000, filas: rows.map((r) => ({ id: r.piece_id, tipo: r.kind, estado: r.status, coste_usd: r.cost_total_usd, url: r.youtube_url, motivo: r.review_reason })) } }];
